func:
const p = msg.payload;
const nome = (p.nome || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const cor = p.cor || '#b7362f';
const visitante_user = p.visitante_user || 'Visitante';
const visitante_pass = p.visitante_pass;
if (!nome) { node.error('nome do cliente obrigatorio', msg); return null; }
if (!visitante_pass) { node.error('senha do cliente obrigatoria', msg); return null; }
const _lock = global.get('op_cliente_lock');
const _stale = _lock && (Date.now() - _lock.desde) > 10 * 60 * 1000;
if (_lock && _lock.ativo && !_stale) {
    node.status({fill:'red', shape:'ring', text:'sistema ocupado'});
    node.error(`bloqueado -- ja tem uma operacao em andamento (${_lock.tipo}: ${_lock.nome})`, msg);
    return [null, { payload: { ok: false, erro: `Sistema ocupado com outra operacao (${_lock.tipo}: ${_lock.nome}). Espere terminar antes de criar um cliente novo.` } }];
}
global.set('op_cliente_lock', { ativo: true, tipo: 'criar', nome: nome, desde: Date.now() });
const logo_base64 = p.logo_base64 || null;
const logo_ext = (p.logo_ext || 'png').replace(/[^a-z0-9]/gi, '') || 'png';
msg.ctx = { nome, cor, visitante_user, visitante_pass, tentativas: 0, logo_base64, logo_ext };
msg.payload = `${nome} "${cor}" "${visitante_user}"`;
const proc = { stepReset: true, stepUpdates: [{key:'provisiona', state:'running'}] };
return [msg, proc];

if (!/=== OK: cliente/.test(msg.payload)) {
    node.status({fill:"red", shape:"ring", text:"provisionamento falhou"});
    node.send([null, {stepUpdates:[{key:'provisiona', state:'erro'}]}]);
    global.set('op_cliente_lock', { ativo: false });
    node.error("provisionamento falhou: " + msg.payload, msg);
    return null;
}
const ctx = msg.ctx;
const m = /PORTA=(\d+)/.exec(msg.payload);
if (!m) {
    node.send([null, {stepUpdates:[{key:'provisiona', state:'erro'}]}]);
    global.set('op_cliente_lock', { ativo: false });
    node.error('nao consegui ler a porta escolhida', msg);
    return null;
}
ctx.porta = m[1];
ctx.container = `stack-scadalts-${ctx.nome}-1`;
msg.payload = `until curl -s -o /dev/null -w '%{http_code}' http://${ctx.container}:8080/Scada-LTS/login.htm | grep -q 200; do sleep 3; done; echo PRONTO`;
node.status({fill:"yellow", shape:"dot", text:`${ctx.nome}: aguardando tomcat subir...`});
const statusMsg = { stepUpdates: [{key:'provisiona', state:'done'}, {key:'boot', state:'running'}] };
return [msg, statusMsg];

const ctx = msg.ctx;
msg.url = `http://${ctx.container}:8080/Scada-LTS/login.htm`;
msg.method = "POST";
msg.headers = { "content-type": "application/x-www-form-urlencoded" };
msg.payload = "username=admin&password=admin";
const statusMsg = { stepUpdates: [{key:'supervisor', state:'running'}] };
return [msg, statusMsg];

const ctx = msg.ctx;
let sessionId = null;
if (msg.redirectList && msg.redirectList.length) {
    for (const r of msg.redirectList) {
        if (r.cookies && r.cookies.JSESSIONID) { sessionId = r.cookies.JSESSIONID.value; break; }
    }
}
if (!sessionId && msg.headers && msg.headers['set-cookie']) {
    const raw = Array.isArray(msg.headers['set-cookie']) ? msg.headers['set-cookie'][0] : msg.headers['set-cookie'];
    const m = /JSESSIONID=([^;]+)/.exec(raw);
    if (m) sessionId = m[1];
}
if (!sessionId) {
    node.status({fill:"red", shape:"ring", text:`${ctx.nome}: login falhou apos tomcat responder`});
    node.error(`${ctx.nome}: login admin/admin falhou mesmo com tomcat de pe -- checar manualmente`, msg);
    return null;
}
ctx.cookie = `JSESSIONID=${sessionId}`;
node.status({fill:"green", shape:"dot", text:`${ctx.nome}: logado, criando usuarios...`});
return msg;

const ctx = msg.ctx;
msg.url = `http://${ctx.container}:8080/Scada-LTS/api/users/`;
msg.method = "POST";
msg.headers = { "content-type": "application/json", "cookie": ctx.cookie };
msg.payload = JSON.stringify({
    username: "Supervisor",
    password: "trocar123",
    email: `supervisor@${ctx.nome}.local`,
    admin: true,
    disabled: false,
    theme: "DEFAULT",
    lang: "pt"
});
return msg;

const ctx = msg.ctx;
msg.url = `http://${ctx.container}:8080/Scada-LTS/api/users/`;
msg.method = "POST";
msg.headers = { "content-type": "application/json", "cookie": ctx.cookie };
msg.payload = JSON.stringify({
    username: ctx.visitante_user,
    password: ctx.visitante_pass,
    email: `${ctx.visitante_user.toLowerCase()}@${ctx.nome}.local`,
    admin: false,
    disabled: false,
    hideMenu: true,
    homeUrl: "/graphics/home.html",
    theme: "DEFAULT",
    lang: "pt"
});
const statusMsg = { stepUpdates: [{key:'supervisor', state:'done'}, {key:'visitante', state:'running'}] };
return [msg, statusMsg];

node.warn(`fn_resultado_final rodando pra ${msg.ctx ? msg.ctx.nome : '???'}`);
const ctx = msg.ctx;
node.status({fill:"green", shape:"dot", text:`cliente ${ctx.nome} pronto (porta ${ctx.porta})`});
msg.stepUpdates = [{key:'visitante', state:'done'}, {key:'pronto', state:'done'}];
msg.payload = {
    ok: true,
    cliente: ctx.nome,
    porta: ctx.porta,
    url: `http://__TAILSCALE_IP_DA_VM__:${ctx.porta}/Scada-LTS/login.htm`,
    supervisor: `Supervisor / trocar123 (gestao interna)`,
    visitante: `${ctx.visitante_user} / (senha definida no formulario) -- login do cliente`
};
return msg;

if (!/PRONTO/.test(msg.payload)) {
    const ctx = msg.ctx;
    node.status({fill:"red", shape:"ring", text:`${ctx.nome}: tomcat nao respondeu em 240s`});
    node.send([null, {stepUpdates:[{key:'boot', state:'erro'}]}]);
    global.set('op_cliente_lock', { ativo: false });
    node.error(`${ctx.nome}: timeout esperando tomcat responder (240s) -- VM pode estar sobrecarregada`, msg);
    return null;
}
const statusMsg = { stepUpdates: [{key:'boot', state:'done'}] };
return [msg, statusMsg];

const ctx = msg.ctx;
const pass = '__MYSQL_ROOT_PASSWORD__';
const sql = `UPDATE users SET lang='pt' WHERE username IN ('Supervisor','${ctx.visitante_user}');`;
msg.payload = `docker exec mysql mysql -uroot -p${pass} scadalts_${ctx.nome} -e "${sql}" && docker restart ${ctx.container} && until curl -s -o /dev/null -w '%{http_code}' http://${ctx.container}:8080/Scada-LTS/login.htm | grep -q 200; do sleep 3; done; echo LANG_OK`;
const statusMsg = { stepUpdates: [{key:'visitante', state:'done'}, {key:'idioma', state:'running'}] };
return [msg, statusMsg];

if (!/LANG_OK/.test(msg.payload)) {
    const ctx = msg.ctx;
    node.status({fill:"red", shape:"ring", text:`${ctx.nome}: falha ajustando idioma`});
    node.send([null, {stepUpdates:[{key:'idioma', state:'erro'}]}]);
    global.set('op_cliente_lock', { ativo: false });
    node.error(`${ctx.nome}: falha ao ajustar idioma/reiniciar`, msg);
    return null;
}
node.warn(`langfix ok pra ${msg.ctx.nome}, seguindo pra fn_resultado_final`);
const statusMsg = { stepUpdates: [{key:'idioma', state:'done'}] };
return [msg, statusMsg];

global.set('op_cliente_lock', { ativo: false });
const ctx = msg.ctx;
const registro = {
    nome: ctx.nome,
    cor: ctx.cor,
    porta: ctx.porta,
    url: `http://__TAILSCALE_IP_DA_VM__:${ctx.porta}/Scada-LTS/login.htm`,
    supervisor_user: 'Supervisor',
    supervisor_pass: 'trocar123',
    visitante_user: ctx.visitante_user,
    visitante_pass: ctx.visitante_pass,
    criado_em: new Date().toISOString(),
};
const linha = JSON.stringify(registro) + '\n';
const b64 = Buffer.from(linha, 'utf8').toString('base64');
msg.payload = `echo ${b64} | base64 -d >> /opt/scadalts/stack/clients_registry.jsonl`;
node.warn(`registro montado pra ${ctx.nome}, mandando pro exec de salvar`);
return msg;

const partes = msg.payload.split('---ATIVOS---');
const registroTxt = (partes[0] || '').trim();
const resto = (partes[1] || '').split('---HEALTH---');
const ativosTxt = (resto[0] || '').trim();
const healthTxt = (resto[1] || '').trim();

const ativos = ativosTxt ? ativosTxt.split('\n').map(s => s.trim()) : [];
const health = {};
if (healthTxt) {
    healthTxt.split('\n').forEach(function(l) {
        const m = /^(.+):(\d+)$/.exec(l.trim());
        if (m) health[m[1]] = m[2];
    });
}

const linhas = registroTxt ? registroTxt.split('\n') : [];
const porNome = {};
for (const l of linhas) {
    if (!l.trim()) continue;
    try {
        const r = JSON.parse(l);
        porNome[r.nome] = r;
    } catch (e) {}
}

const clientes = Object.values(porNome)
    .filter(r => ativos.includes(`stack-scadalts-${r.nome}-1`))
    .map(function(r) {
        const code = health[`stack-scadalts-${r.nome}-1`];
        r.status = code === '200' ? 'ok' : 'erro';
        r.statusCode = code || '-';
        return r;
    });
clientes.sort((a, b) => (a.nome > b.nome ? 1 : -1));
msg.payload = clientes;
return msg;

if (Array.isArray(msg.payload)) {
    return [null, null, null];
}
if (msg.payload && msg.payload.action === 'publicar') {
    return [null, msg, null];
}
if (msg.payload && msg.payload.action === 'excluir') {
    return [null, null, msg];
}
return [msg, null, null];

const CF_TOKEN = "__CF_API_TOKEN__";
const ZONE_ID = "__CF_ZONE_ID__";
const cliente = msg.payload.cliente;
const hostname = `${cliente.nome}.__SEU_DOMINIO__`;
const _lock = global.get('op_cliente_lock');
const _stale = _lock && (Date.now() - _lock.desde) > 10 * 60 * 1000;
if (_lock && _lock.ativo && !_stale) {
    const proc = {
        procReset: { titulo: `Publicar ${hostname}`, steps: [{key:'dns', label:'Verificar disponibilidade'}]},
        stepUpdates: [{key:'dns', state:'erro'}], procDone: true,
        procErro: `Sistema ocupado com outra operacao (${_lock.tipo}: ${_lock.nome}). Espere terminar antes de publicar.`,
    };
    node.error(`publicacao de ${hostname} bloqueada: sistema ocupado (${_lock.tipo}: ${_lock.nome})`, msg);
    return [null, proc];
}
global.set('op_cliente_lock', { ativo: true, tipo: 'publicar', nome: cliente.nome, desde: Date.now() });
flow.set('dominio_ctx', { clienteInfo: cliente, hostname: hostname });
msg.url = `https://api.cloudflare.com/client/v4/zones/${ZONE_ID}/dns_records`;
msg.method = 'POST';
msg.headers = { 'Authorization': `Bearer ${CF_TOKEN}`, 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({
    type: 'CNAME',
    content: "__CF_TUNNEL_ID__.cfargotunnel.com",
    name: hostname,
    proxied: true,
});
const proc = {
    procReset: { titulo: `Publicando domínio: ${hostname}`, steps: [
        {key:'dns', label:'Criando registro DNS'},
        {key:'ingress', label:'Atualizando túnel'},
        {key:'pronto', label:'Publicado'},
    ]},
    stepUpdates: [{key:'dns', state:'running'}],
};
return [msg, proc];

const r = msg.payload;
const jaExiste = !r.success && (r.errors || []).some(e => e.code === 81057 || e.code === 81053);
if (!r.success && !jaExiste) {
    global.set('op_cliente_lock', { ativo: false });
    node.status({fill:'red', shape:'ring', text:'falha ao criar DNS'});
    node.send([null, {stepUpdates:[{key:'dns', state:'erro'}], procDone:true, procErro:'Falha ao criar registro DNS: ' + JSON.stringify(r.errors)}]);
    node.error('falha ao criar registro DNS: ' + JSON.stringify(r.errors), msg);
    return null;
}
node.status({fill:'green', shape:'dot', text:`DNS ok: ${msg.hostname}`});
const proc = { stepUpdates: [{key:'dns', state:'done'}, {key:'ingress', state:'running'}] };
return [msg, proc];

const ctx = flow.get('dominio_ctx') || {};
msg.clienteInfo = ctx.clienteInfo;
msg.hostname = ctx.hostname;
const cliente = msg.clienteInfo;
const hostname = msg.hostname;
const yaml = msg.payload;
let novoYaml = yaml;
if (!yaml.includes(hostname)) {
    const catchall = '  - service: http_status:404';
    const novaRegra = `  - hostname: ${hostname}\n    service: http://__TAILSCALE_IP_DA_VM__:${cliente.porta}\n`;
    novoYaml = yaml.replace(catchall, novaRegra + catchall);
}
const b64 = Buffer.from(novoYaml, 'utf8').toString('base64');
msg.payload = `echo ${b64} | base64 -d > /etc/cloudflared/config.yml`;
return msg;

global.set('op_cliente_lock', { ativo: false });
const ctx = flow.get('dominio_ctx') || {};
const cliente = ctx.clienteInfo;
const hostname = ctx.hostname;
const registro = Object.assign({}, cliente, { dominio_url: `https://${hostname}/Scada-LTS/login.htm` });
delete registro.status;
delete registro.statusCode;
const linha = JSON.stringify(registro) + '\n';
const b64 = Buffer.from(linha, 'utf8').toString('base64');
msg.payload = `echo ${b64} | base64 -d >> /opt/scadalts/stack/clients_registry.jsonl`;
node.status({fill:'green', shape:'dot', text:`dominio publicado: ${hostname}`});
const proc = { stepUpdates: [{key:'ingress', state:'done'}, {key:'pronto', state:'done'}], procDone: true };
return [msg, proc];

const MASTER = "__MASTER_PASSWORD_EXCLUIR__";
const body = msg.payload;
if (body.senha !== MASTER) {
    node.status({fill:'red', shape:'ring', text:'senha mestra incorreta -- nada foi apagado'});
    node.error(`exclusao de ${body.cliente.nome} bloqueada: senha mestra incorreta`, msg);
    const proc = {
        procReset: { titulo: `Excluir ${body.cliente.nome}`, steps: [
            {key:'senha', label:'Confirmar senha mestra'},
        ]},
        stepUpdates: [{key:'senha', state:'erro'}],
        procDone: true,
        procErro: 'Senha mestra incorreta -- nada foi apagado.',
    };
    return [null, proc];
}
const _lock = global.get('op_cliente_lock');
const _stale = _lock && (Date.now() - _lock.desde) > 10 * 60 * 1000;
if (_lock && _lock.ativo && !_stale) {
    const proc = {
        procReset: { titulo: `Excluir ${body.cliente.nome}`, steps: [{key:'senha', label:'Verificar disponibilidade'}]},
        stepUpdates: [{key:'senha', state:'erro'}], procDone: true,
        procErro: `Sistema ocupado com outra operacao (${_lock.tipo}: ${_lock.nome}). Espere terminar antes de excluir.`,
    };
    node.error(`exclusao de ${body.cliente.nome} bloqueada: sistema ocupado (${_lock.tipo}: ${_lock.nome})`, msg);
    return [null, proc];
}
global.set('op_cliente_lock', { ativo: true, tipo: 'excluir', nome: body.cliente.nome, desde: Date.now() });
flow.set('exclusao_ctx', body.cliente);
node.status({fill:'yellow', shape:'dot', text:`excluindo ${body.cliente.nome}...`});
const proc = {
    procReset: { titulo: `Excluindo cliente: ${body.cliente.nome}`, steps: [
        {key:'dns', label:'Removendo DNS'},
        {key:'ingress', label:'Removendo túnel'},
        {key:'purga', label:'Fazendo backup e apagando'},
        {key:'pronto', label:'Excluído'},
    ]},
    stepUpdates: [{key:'dns', state:'running'}],
};
return [msg, proc];

const CF_TOKEN = "__CF_API_TOKEN__";
const ZONE_ID = "__CF_ZONE_ID__";
const cliente = flow.get('exclusao_ctx');
const hostname = `${cliente.nome}.__SEU_DOMINIO__`;
msg.url = `https://api.cloudflare.com/client/v4/zones/${ZONE_ID}/dns_records?name=${hostname}`;
msg.method = 'GET';
msg.headers = { 'Authorization': `Bearer ${CF_TOKEN}` };
return msg;

const CF_TOKEN = "__CF_API_TOKEN__";
const ZONE_ID = "__CF_ZONE_ID__";
const r = msg.payload;
const rec = (r && r.result || [])[0];
const proc = { stepUpdates: [{key:'dns', state:'done'}, {key:'ingress', state:'running'}] };
if (!rec) { return [null, msg, proc]; }
msg.url = `https://api.cloudflare.com/client/v4/zones/${ZONE_ID}/dns_records/${rec.id}`;
msg.method = 'DELETE';
msg.headers = { 'Authorization': `Bearer ${CF_TOKEN}` };
return [msg, null, proc];

const cliente = flow.get('exclusao_ctx');
const hostname = `${cliente.nome}.__SEU_DOMINIO__`;
const yaml = msg.payload;
const bloco = `  - hostname: ${hostname}\n    service: http://__TAILSCALE_IP_DA_VM__:${cliente.porta}\n`;
const novoYaml = yaml.includes(bloco) ? yaml.replace(bloco, '') : yaml;
const b64 = Buffer.from(novoYaml, 'utf8').toString('base64');
msg.payload = `echo ${b64} | base64 -d > /etc/cloudflared/config.yml`;
return msg;

global.set('op_cliente_lock', { ativo: false });
const cliente = flow.get('exclusao_ctx');
if (!/EXCLUSAO_OK/.test(msg.payload)) {
    node.status({fill:'red', shape:'ring', text:`falha ao excluir ${cliente.nome}`});
    node.send([null, {stepUpdates:[{key:'purga', state:'erro'}], procDone:true, procErro:`Falha ao excluir ${cliente.nome} -- verificar manualmente.`}]);
    node.error(`falha ao excluir ${cliente.nome} -- checar manualmente`, msg);
    return null;
}
node.status({fill:'green', shape:'dot', text:`${cliente.nome} excluido e arquivado`});
const proc = { stepUpdates: [{key:'purga', state:'done'}, {key:'pronto', state:'done'}], procDone: true };
return [{ payload: 'refresh' }, proc];

const antes = global.get('op_cliente_lock');
global.set('op_cliente_lock', { ativo: false });
node.warn('trava liberada manualmente. estado anterior: ' + JSON.stringify(antes));
return msg;

const ctx = msg.ctx;
if (!ctx.logo_base64) {
    msg.payload = 'true';
    return msg;
}
const dir = `/opt/scadalts/stack/clients/${ctx.nome}/graphics`;
msg.payload = `mkdir -p ${dir} && echo ${ctx.logo_base64} | base64 -d > ${dir}/logo.${ctx.logo_ext} && echo LOGO_OK`;
return msg;
